from interops.libraries.desktop import AutManager

class FailedToFindObject(Exception):
    """
    Thrown when an object is failed to be found in the active AUT context
    """
    def __init__(self, objectMap) -> None:
        current_aut_context = AutManager.get_aut_name_of_current_context()
        message = f"""No Object using Object Map: {objectMap} was found in the current AUT context: {current_aut_context}"""
        super().__init__(message)

class AutRuntimeError(RuntimeError):
    """
    Thrown when an AUT is expected to be running but isn't
    """
    def __init__(self, autName: str) -> None:
        message = f"""No {autName} window is open within the squish context"""
        super().__init__(message)